-- Arbeitsrecht Berufsbildung > Wirtschafts- und Sozialkunde > Gemeinkosten
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Zählen die Mietkosten für ein Büro zu den Gemeinkosten eines IT-Betriebs?', 2, '[{"text": "Ja", "correct": true, "because": "Mietkosten sind Gemeinkosten, da sie nicht direkt einem Produkt zugeordnet werden"}, {"text": "Nein", "correct": false, "because": "Mietkosten gehören zu den Gemeinkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind die Kosten für Programmierlizenzen eines Fachinformatikers Gemeinkosten?', 2, '[{"text": "Ja", "correct": true, "because": "Lizenzen sind oft Gemeinkosten, wenn sie nicht direkt einem Projekt zurechenbar sind"}, {"text": "Nein", "correct": false, "because": "Lizenzen können Gemeinkosten sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Gemeinkosten in einem IT-Betrieb auf einzelne Projekte verteilt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Verteilung der Gemeinkosten ist für die Kostenrechnung üblich"}, {"text": "Nein", "correct": false, "because": "Verteilung ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Gemeinkosten wie Stromkosten eines IT-Betriebs variabel sein?', 2, '[{"text": "Ja", "correct": true, "because": "Stromkosten können je nach Nutzung variieren"}, {"text": "Nein", "correct": false, "because": "Gemeinkosten können variabel sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind die Gehälter von Fachinformatikern Gemeinkosten?', 2, '[{"text": "Nein", "correct": true, "because": "Gehälter sind meist Einzelkosten, wenn sie einem Projekt zurechenbar sind"}, {"text": "Ja", "correct": false, "because": "Gehälter sind oft Einzelkosten"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kosten zählen typischerweise zu den Gemeinkosten eines IT-Betriebs?', 2, '[{"text": "Mietkosten für Serverräume", "correct": true, "because": "Mietkosten sind Gemeinkosten"}, {"text": "Kosten für spezielle Projektsoftware", "correct": false, "because": "Projektkosten sind Einzelkosten"}, {"text": "Materialkosten für Hardware", "correct": false, "because": "Materialkosten sind Einzelkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie werden Gemeinkosten in einem IT-Betrieb üblicherweise verteilt?', 3, '[{"text": "Über Zuschlagssätze auf Einzelkosten", "correct": true, "because": "Zuschlagssätze sind Standard in der Kostenrechnung"}, {"text": "Nur direkt den Projekten zugeordnet", "correct": false, "because": "Gemeinkosten sind nicht direkt zuordenbar"}, {"text": "Willkürlich ohne System", "correct": false, "because": "Systematische Verteilung ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart gehört nicht zu den Gemeinkosten eines IT-Betriebs?', 3, '[{"text": "Kosten für spezifische Projekt-Hardware", "correct": true, "because": "Projektspezifisch, daher Einzelkosten"}, {"text": "Stromkosten für Büroräume", "correct": false, "because": "Gemeinkosten"}, {"text": "Abschreibungen auf Bürogeräte", "correct": false, "because": "Gemeinkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer trägt in einem IT-Betrieb typischerweise die Gemeinkosten?', 2, '[{"text": "Alle Projekte gemeinsam", "correct": true, "because": "Gemeinkosten werden auf Projekte verteilt"}, {"text": "Nur das größte Projekt", "correct": false, "because": "Ungerechte Verteilung"}, {"text": "Der Auszubildende", "correct": false, "because": "Nicht seine Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn Gemeinkosten eines IT-Betriebs nicht korrekt verteilt werden?', 3, '[{"text": "Die Projektkosten werden verzerrt", "correct": true, "because": "Fehlerhafte Verteilung beeinflusst Kalkulation"}, {"text": "Die Gemeinkosten verschwinden", "correct": false, "because": "Kosten bleiben bestehen"}, {"text": "Keine Auswirkungen", "correct": false, "because": "Verzerrung hat Folgen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kosten zählen zu den Gemeinkosten eines IT-Betriebs?', 4, '[{"text": "Mietkosten für Büroräume", "correct": true, "because": "Nicht direkt zurechenbar"}, {"text": "Stromkosten für Server", "correct": true, "because": "Gemeinkosten, wenn nicht projektspezifisch"}, {"text": "Kosten für spezielle Projektsoftware", "correct": false, "because": "Einzelkosten"}, {"text": "Abschreibungen auf Bürogeräte", "correct": true, "because": "Gemeinkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben Gemeinkosten in einem IT-Betrieb?', 3, '[{"text": "Nicht direkt einem Projekt zurechenbar", "correct": true, "because": "Definition von Gemeinkosten"}, {"text": "Können fix oder variabel sein", "correct": true, "because": "Beispiel Miete vs. Strom"}, {"text": "Immer projektspezifisch", "correct": false, "because": "Nicht zurechenbar"}, {"text": "Werden auf Projekte verteilt", "correct": true, "because": "Kostenrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden werden verwendet, um Gemeinkosten in einem IT-Betrieb zu verteilen?', 4, '[{"text": "Zuschlagssätze auf Arbeitsstunden", "correct": true, "because": "Übliche Methode"}, {"text": "Verteilung nach Umsatz", "correct": true, "because": "Mögliche Verteilung"}, {"text": "Keine Verteilung", "correct": false, "because": "Verteilung ist erforderlich"}, {"text": "Verteilung nach Mitarbeiterzahl", "correct": true, "because": "Alternative Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten sind keine Gemeinkosten in einem IT-Betrieb?', 3, '[{"text": "Kosten für spezifische Projekt-Hardware", "correct": true, "because": "Einzelkosten"}, {"text": "Stromkosten für Büroräume", "correct": false, "because": "Gemeinkosten"}, {"text": "Gehälter der Verwaltung", "correct": false, "because": "Gemeinkosten"}, {"text": "Abschreibungen auf Server", "correct": false, "because": "Gemeinkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen haben Gemeinkosten auf die Kalkulation in einem IT-Betrieb?', 3, '[{"text": "Erhöhen die Gesamtkosten", "correct": true, "because": "Gemeinkosten sind Teil der Kosten"}, {"text": "Beeinflussen die Projektkalkulation", "correct": true, "because": "Durch Verteilung relevant"}, {"text": "Kein Einfluss", "correct": false, "because": "Gemeinkosten sind relevant"}, {"text": "Nur direkte Projektkosten", "correct": false, "because": "Gemeinkosten sind indirekt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Mietkosten sind Gemeinkosten eines IT-Betriebs. b) Kosten für Projektsoftware sind Gemeinkosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mietkosten ja, Projektsoftware nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gemeinkosten werden auf Projekte verteilt. b) Stromkosten können Gemeinkosten sein.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Verteilung und Strom als Gemeinkosten"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Gehälter von Fachinformatikern sind immer Gemeinkosten. b) Abschreibungen auf Bürogeräte sind Gemeinkosten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Abschreibungen ja, Gehälter nein"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Gemeinkosten können variabel sein. b) Sie müssen immer fix sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Variabel möglich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zuschlagssätze verteilen Gemeinkosten auf Projekte. b) Gemeinkosten beeinflussen die Kalkulation nicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zuschlagssätze ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

